fn unique_id(prefix: &str) -> String {
    let mut bytes = [0_u8; 8];
    getrandom::getrandom(&mut bytes).expect("the OS random source should be available");
    let suffix: String = bytes.iter().map(|byte| format!("{byte:02x}")).collect();
    format!("{prefix}-{suffix}")
}

async fn enroll_repository(database_url: &str, tenant_id: &str, repository_id: &str, unique: &str) {
    let seed: [u8; 32] = Sha256::digest(format!("key-{unique}").as_bytes()).into();
    let signing_key = SigningKey::from_bytes(&seed);
    let public_key = signing_key.verifying_key().to_bytes();
    let request_id = format!("request-{unique}");
    let node_id = format!("node-{unique}");
    let fingerprint = public_key_fingerprint(&public_key);
    let submission = EnrollmentSubmission {
        request_id: request_id.clone(),
        tenant_id: tenant_id.to_string(),
        repository_id: repository_id.to_string(),
        proposed_node_id: node_id.clone(),
        display_name: "Work command API integration node".to_string(),
        public_key: public_key.to_vec(),
        public_key_fingerprint: fingerprint.clone(),
        requested_capabilities: vec!["synchronize".to_string()],
        created_at: "2026-01-01T00:00:00Z".to_string(),
        expires_at: "2030-01-01T00:00:00Z".to_string(),
    };
    let request = ActivationChallengeRequest {
        request_id,
        tenant_id: tenant_id.to_string(),
        repository_id: repository_id.to_string(),
        proposed_node_id: node_id,
        public_key_fingerprint: fingerprint,
    };
    let mut enrollment = EnrollmentStore::connect(database_url)
        .await
        .expect("connect enrollment store");
    enrollment
        .submit(&submission)
        .await
        .expect("submit enrollment");
    enrollment
        .approve(&EnrollmentApproval {
            request_id: submission.request_id.clone(),
            tenant_id: tenant_id.to_string(),
            repository_id: repository_id.to_string(),
            public_key_fingerprint: submission.public_key_fingerprint.clone(),
            approved_capabilities: submission.requested_capabilities.clone(),
            approved_by: "work-command-api-integration-administrator".to_string(),
        })
        .await
        .expect("approve enrollment");
    let nonce: [u8; 32] = Sha256::digest(format!("nonce-{unique}").as_bytes()).into();
    let challenge = enrollment
        .issue_challenge(&request, &nonce, std::time::SystemTime::now())
        .await
        .expect("issue enrollment challenge");
    let signature = signing_key.sign(&activation_challenge_bytes(
        &challenge.nonce,
        &request.request_id,
        &request.tenant_id,
        &request.repository_id,
        &request.proposed_node_id,
        &request.public_key_fingerprint,
    ));
    enrollment
        .activate(
            &EnrollmentActivation {
                request,
                nonce: challenge.nonce,
                signature: signature.to_bytes().to_vec(),
            },
            &format!("receipt-{unique}"),
            &format!("signing-key-{unique}"),
            std::time::SystemTime::now(),
        )
        .await
        .expect("activate enrollment");
}

async fn application(database_url: &str, tenant_id: &str) -> axum::Router {
    let db_pool = ackplane_server::db_pool::build_pool(
        database_url,
        ackplane_server::db_pool::TEST_POOL_MAX_SIZE,
    )
    .expect("the gated test database url builds a pool");
    let commands = Arc::new(
        WorkCommandService::connect(&db_pool)
            .await
            .expect("connect Work command service"),
    );
    let fleet = Arc::new(
        FleetStore::connect(database_url)
            .await
            .expect("connect Fleet store"),
    );
    work_command_routes(WorkCommandApiState::new(
        commands,
        fleet,
        Arc::from(tenant_id.to_string()),
    ))
}

/// The nine non-`create_work` command kinds require an existing target
/// (`work_commands.task_id` has an `ON DELETE RESTRICT` foreign key against
/// `work_tasks`), so a verified-in-scope submission that targets one now
/// really does insert a row -- unlike the permanently-`authorization_unavailable`
/// profile this ADR-0142 test suite replaces, which never reached the store
/// at all. Seed the real task these fixtures target before submitting.
async fn seed_task(database_url: &str, tenant_id: &str, repository_id: &str, task_id: &str) {
    let mut work_store = ackplane_server::work_store::WorkStore::connect(database_url)
        .await
        .expect("connect Work store");
    work_store
        .create_task(
            &ackplane_server::work_store::NewWorkTask {
                tenant_id: tenant_id.to_string(),
                repository_id: repository_id.to_string(),
                task_id: task_id.to_string(),
                title: "A task these Work command fixtures can target".to_string(),
                acceptance: "The task exists so a command referencing it is not an FK violation."
                    .to_string(),
                goal_id: None,
                declared_paths: Vec::new(),
                declared_symbols: Vec::new(),
                published_by: format!("publisher-{task_id}"),
            },
            &format!("event-{task_id}"),
            std::time::SystemTime::now(),
        )
        .await
        .expect("seeding the task should succeed");
}

async fn post_json(router: &axum::Router, uri: &str, body: Value) -> (StatusCode, Value) {
    let response = router
        .clone()
        .oneshot(
            Request::builder()
                .method("POST")
                .uri(uri)
                .header("content-type", "application/json")
                .body(Body::from(body.to_string()))
                .expect("the request should build"),
        )
        .await
        .expect("the request should receive a response");
    let status = response.status();
    let bytes = to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("the response body should be bounded");
    let json = if bytes.is_empty() {
        Value::Null
    } else {
        serde_json::from_slice(&bytes).unwrap_or_else(|error| {
            panic!(
                "a non-empty response body should be JSON: {error}; raw body: {:?}",
                String::from_utf8_lossy(&bytes)
            )
        })
    };
    (status, json)
}

/// Common envelope fields every command kind needs, merged with the
/// kind-specific fields the caller supplies. `principal_id` must equal the
/// Bridge's own `tenant_id` (ADR-0142 clause 2: the verified principal's
/// `principal_id` is the salted `development_tenant_token` itself) for the
/// command to be authorized rather than refused as a forged principal.
/// Every existing-task command also needs `expected_task_version` (the
/// store refuses `MissingExistingTaskVersion` otherwise); `1` is
/// `seed_task`'s freshly created task's starting version.
fn envelope(principal_id: &str, existing_task_id: Option<&str>, mut payload: Value) -> Value {
    payload["issuing_principal_id"] = json!(principal_id);
    payload["idempotency_key"] = json!(unique_id("idempotency"));
    payload["rationale"] = json!("Exercise the ADR-0125 Work command contract end to end.");
    payload["policy_refs"] = json!([]);
    payload["expires_at_seconds"] = json!(4_000_000_000_u64);
    if let Some(existing_task_id) = existing_task_id {
        payload["existing_task_id"] = json!(existing_task_id);
        payload["expected_task_version"] = json!(1);
    }
    payload
}

