/// ADR-0142 unlocks these ten command routes for a self-hosted, single-tenant
/// deployment: the hardened loopback token is now a verified principal
/// (clause 2), so a well-formed, correctly-attributed request records a real
/// `pending_confirmation` preview -- never the permanent
/// `authorization_unavailable` refusal ADR-0125 shipped before this ADR.
#[tokio::test]
async fn every_command_kind_records_a_pending_confirmation_under_the_verified_loopback_principal() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let unique = unique_id("work-command-api");
    let tenant_id = format!("tenant-{unique}");
    let repository_id = format!("repository-{unique}");
    enroll_repository(&database_url, &tenant_id, &repository_id, &unique).await;
    seed_task(&database_url, &tenant_id, &repository_id, "existing-task-1").await;
    let app = application(&database_url, &tenant_id).await;

    for (kind, body) in command_fixtures(&tenant_id) {
        let uri = format!("/api/v1/repositories/{repository_id}/work/commands");
        let (status, json) = post_json(&app, &uri, body).await;
        assert_eq!(
            status,
            StatusCode::OK,
            "{kind} should be a well-formed request"
        );
        assert_eq!(
            json["status"],
            json!("pending_confirmation"),
            "{kind} must execute under the ADR-0142 verified loopback principal, got {json:?}"
        );
        assert_eq!(json["idempotent_replay"], json!(false));
    }
}

/// A request `issuing_principal_id` that does not match the Bridge's own
/// `tenant_id` is still refused, exactly as ADR-0142 clause 2 requires --
/// the loopback profile is a real, un-forgeable principal, not a synonym
/// for "anyone who asks."
#[tokio::test]
async fn a_forged_issuing_principal_is_still_refused() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let unique = unique_id("work-command-api-forged-principal");
    let tenant_id = format!("tenant-{unique}");
    let repository_id = format!("repository-{unique}");
    enroll_repository(&database_url, &tenant_id, &repository_id, &unique).await;
    let app = application(&database_url, &tenant_id).await;

    let uri = format!("/api/v1/repositories/{repository_id}/work/commands");
    let (status, json) = post_json(
        &app,
        &uri,
        envelope(
            "not-the-real-tenant-token",
            None,
            json!({
                "kind": "create_work",
                "task_id": "new-task-1",
                "title": "A task a forged principal should not be able to create",
                "acceptance": "Acceptance criteria for the new task.",
            }),
        ),
    )
    .await;
    assert_eq!(status, StatusCode::OK);
    assert_eq!(
        json,
        json!({
            "status": "refused",
            "reason": "forged_principal",
        })
    );
}

/// Confirming an id no command was ever submitted under reaches
/// `CommandNotFound` -- the authorization check no longer refuses the
/// self-hosted loopback principal outright (ADR-0142), so this is the first
/// real signal a caller sees for an unknown command id.
#[tokio::test]
async fn confirming_an_unsubmitted_command_reports_command_not_found() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let unique = unique_id("work-command-api-confirm");
    let tenant_id = format!("tenant-{unique}");
    let repository_id = format!("repository-{unique}");
    enroll_repository(&database_url, &tenant_id, &repository_id, &unique).await;
    let app = application(&database_url, &tenant_id).await;

    let uri = format!(
        "/api/v1/repositories/{repository_id}/work/commands/never-submitted-command/confirm"
    );
    let (status, json) = post_json(
        &app,
        &uri,
        json!({"kind": "assign", "target_node_id": "node-1", "target_session_id": "session-1"}),
    )
    .await;
    assert_eq!(status, StatusCode::OK);
    assert_eq!(json, json!({"status": "command_not_found"}));
}

